styles.css:
:where(h1, h2, h3, h4) { text-wrap: balance; }
:where(p, li) { text-wrap: pretty; }
:where(a, button, input, select, textarea, summary):focus-visible { outline: 3px solid var(--wp--preset--color--stage); outline-offset: 3px; }
.is-style-section-night :where(a, button, summary):focus-visible, .site-footer :where(a, button):focus-visible, .wp-block-navigation__responsive-container.is-menu-open :where(a, button):focus-visible { outline-color: var(--wp--preset--color--stage-light); }
.site-header { border-bottom: 1px solid var(--wp--preset--color--rule); }
.site-header .wp-block-navigation-item__content, .wp-block-navigation__responsive-container-open, .wp-block-navigation__responsive-container-close { min-height: 2.75rem; }
.site-header .wp-block-navigation__responsive-container-open, .site-header .wp-block-navigation__responsive-container-close { font-family: var(--wp--preset--font-family--sans); font-weight: 600; font-size: 1rem; padding: .5rem .75rem; border: 2px solid currentColor; border-radius: 2px; }
.site-header .wp-block-navigation-item__content:hover, .site-header .current-menu-item > .wp-block-navigation-item__content { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: .35em; }
@media (min-width: 600px) and (max-width: 1199.98px) {
  .site-header .wp-block-navigation__responsive-container-open:not(.always-shown) { display: flex; }
  .site-header .wp-block-navigation__responsive-container:not(.hidden-by-default):not(.is-menu-open) { display: none; }
}
.wp-block-navigation__responsive-container.is-menu-open { padding: var(--wp--preset--spacing--30) var(--wp--style--root--padding-right, 1.25rem) var(--wp--preset--spacing--60); }
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content { padding-top: var(--wp--preset--spacing--60); }
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item__content { font-size: clamp(1.625rem, 1.2rem + 1.8vw, 2.25rem); font-weight: 600; padding-block: .35rem; }
@media (max-width: 479.98px) { .site-header .header-find { display: none; } }
.site-footer .wp-block-page-list { list-style: none; padding: 0; margin: 0; columns: 2; column-gap: var(--wp--preset--spacing--50); }
@media (min-width: 62rem) { .site-footer .wp-block-page-list { columns: 3; } }
.site-footer .wp-block-page-list a { display: inline-flex; align-items: center; min-height: 2.75rem; color: inherit; text-decoration: none; }
.site-footer .wp-block-page-list a:hover { text-decoration: underline; text-underline-offset: .25em; }
.wp-block-button__link { min-height: 2.75rem; display: inline-flex; align-items: center; justify-content: center; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; scroll-behavior: auto !important; } }
.cacdemo-display { font-weight: 800; line-height: 0.98; letter-spacing: -0.03em; max-width: 11ch; }
.cacdemo-hero-lead { max-width: 30ch; }
.cacdemo-hero-media .wp-block-image img { max-height: 34rem; width: auto; object-fit: contain; }
@media (max-width: 781.98px) {
  .cacdemo-hero .wp-block-columns { display: grid; grid-template-columns: minmax(0, 1fr) 6.5rem; gap: var(--wp--preset--spacing--40); align-items: start; }
  .cacdemo-hero .wp-block-column { grid-row: 1; }
  .cacdemo-hero .wp-block-column:first-child { grid-column: 1 / -1; }
  .cacdemo-hero .wp-block-column.cacdemo-hero-media { grid-column: 2; margin-top: -0.25rem; }
  .cacdemo-hero .cacdemo-hero-media .wp-block-image { float: none; margin: 0; }
  .cacdemo-hero .cacdemo-display { max-width: 9.2ch; }
  .cacdemo-hero .cacdemo-hero-lead { max-width: calc(100% - 7.5rem); }
}
.cacdemo-post-list { border-top: 1px solid currentColor; }
.cacdemo-post-list > li { margin-block-start: 0; padding-block: var(--wp--preset--spacing--50); border-bottom: 1px solid var(--wp--preset--color--rule); }
.screen-reader-text { border: 0; clip-path: inset(50%); height: 1px; margin: -1px; overflow: hidden; padding: 0; position: absolute; width: 1px; word-wrap: normal !important; }
.is-style-section-night .is-style-text-link .wp-block-button__link, .is-style-section-night .is-style-text-link .wp-block-button__link:hover { color: var(--wp--preset--color--stage-light); }
.is-style-section-night .is-style-rows > * { border-bottom-color: var(--wp--preset--color--night-rule); }
.wp-block-quote { margin-inline: 0; }
.is-style-rows :where(h2, h3, h4) a { color: inherit; text-decoration: none; }
.is-style-rows :where(h2, h3, h4) a:hover { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 0.2em; }
.wp-block-post-content > .alignfull, .wp-block-post-content > .alignfull + * { margin-block-start: 0; }
.site-footer .wp-block-site-title a, .site-header .wp-block-site-title a { color: inherit; }
.wp-block-site-title a { display: inline-flex; align-items: center; min-height: 2.75rem; }
.is-style-rows :where(h2, h3, h4) a { display: inline-flex; align-items: center; min-height: 2.75rem; }
.cacdemo-centres:not(:has(.wp-block-post-template > li)):not(:has(.wp-block-query-no-results)) { display: none; }
.cacdemo-centre p:empty, .cacdemo-inline > p:empty { display: none; }
.cacdemo-centre .wp-block-button:has(> .wp-block-button__link:not([href])), .cacdemo-centre .wp-block-button:has(> .wp-block-button__link[href=""]) { display: none; }
.cacdemo-inline > p { margin: 0; }
.cacdemo-inline--comma { column-gap: 0.3em !important; }
.cacdemo-inline--comma > p:not(:empty):has(~ p:not(:empty))::after { content: ","; }
.cacdemo-comma-after:not(:empty)::after { content: ","; }
.cacdemo-meta, .cacdemo-meta p { font-family: var(--wp--preset--font-family--sans); font-size: var(--wp--preset--font-size--small); color: var(--wp--preset--color--stone); }
.cacdemo-visit { border-top: 2px solid currentColor; }
.cacdemo-visit__list > li { border-bottom: 1px solid var(--wp--preset--color--rule); }
.cacdemo-visit__list { column-gap: var(--wp--preset--spacing--70) !important; row-gap: 0 !important; }
.cacdemo-centre__name { font-family: var(--wp--preset--font-family--sans); font-size: 1.25rem; font-weight: 700; }
.cacdemo-centre__when p { font-family: var(--wp--preset--font-family--sans); }
.cacdemo-directory { border-top: 2px solid currentColor; }
.cacdemo-directory > li { border-bottom: 1px solid var(--wp--preset--color--rule); margin-block-start: 0; }
.cacdemo-directory .cacdemo-centre { margin-bottom: 0; }
.cacdemo-directory .wp-block-post-title a { color: inherit; text-decoration: none; display: inline-flex; align-items: center; min-height: 2.75rem; }
.cacdemo-directory .wp-block-post-title a:hover { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 0.2em; }
.cacdemo-fact { font-family: var(--wp--preset--font-family--sans); font-size: 1.125rem; line-height: 1.45; }
.cacdemo-fact > * + * { margin-block-start: var(--wp--preset--spacing--10); }
.cacdemo-fact__label { font-size: var(--wp--preset--font-size--small); color: var(--wp--preset--color--stone); }
.cacdemo-footer-centres { border-bottom: 1px solid var(--wp--preset--color--night-rule); }
.cacdemo-footer-centres .wp-block-post-title a { color: inherit; text-decoration: none; display: inline-flex; min-height: 2.75rem; align-items: center; }
.cacdemo-footer-centres .wp-block-post-template { gap: var(--wp--preset--spacing--60); }
.cacdemo-footer-centres .cacdemo-centre, .cacdemo-visit .cacdemo-centre { font-family: var(--wp--preset--font-family--sans); }
.cacdemo-footer-centres .is-style-text-link .wp-block-button__link { color: var(--wp--preset--color--paper); }
.cacdemo-beliefs { list-style: none; counter-reset: belief; padding: 0; margin-block-start: var(--wp--preset--spacing--60); display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 20rem), 1fr)); column-gap: var(--wp--preset--spacing--70); border-top: 2px solid currentColor; }
.cacdemo-beliefs > li { counter-increment: belief; position: relative; padding-inline-start: 2.25rem; margin: 0; line-height: 1.5; padding-block: var(--wp--preset--spacing--40); border-bottom: 1px solid var(--wp--preset--color--rule); font-family: var(--wp--preset--font-family--sans); font-size: var(--wp--preset--font-size--small); color: var(--wp--preset--color--stone); }
.cacdemo-beliefs > li::before { content: counter(belief); position: absolute; inset-inline-start: 0; font-weight: 700; color: var(--wp--preset--color--stage); font-variant-numeric: tabular-nums; }
.cacdemo-beliefs strong { font-size: 1.0625rem; font-weight: 700; color: var(--wp--preset--color--ink); }
.cacdemo-portrait img { aspect-ratio: 4 / 5; object-fit: cover; object-position: 50% 30%; width: 100%; }
.cacdemo-project-logo { margin-block-end: var(--wp--preset--spacing--50); }
.cacdemo-project-logo img { width: 4.5rem; height: 4.5rem; border-radius: 50%; }
.cacdemo-accent-line { color: var(--wp--preset--color--stage); margin-block-start: var(--wp--preset--spacing--60); }
.cacdemo-page-lead { max-width: 38rem; }
.wp-block-post-content:has(> .alignfull:last-child) { padding-bottom: 0 !important; }
body:has(.wp-block-post-content > .alignfull:last-child) footer.wp-block-template-part { margin-block-start: 0; }
.wp-block-post-content > .cacdemo-centres + .alignfull:not(.is-style-section-mist):not(.is-style-section-night) { padding-top: 0 !important; }
.wp-block-embed-spotify iframe { border-radius: 12px; }
.is-style-rows .wp-block-columns :where(h2, h3, h4) { display: flex; align-items: center; min-height: 2.75rem; }
@media (min-width: 782px) { .is-style-rows .wp-block-columns > .wp-block-column > p:first-child { margin-block-start: 0.55rem; } }
